class Solution:
    # @param {integer[]} nums
    # @return {integer}
    def majorityElement(self, nums):
        counter = Counter()
        max = 0
        maxnum = 0
        for num in nums:
            counter[num]+=1
            if counter[num]>max:
                max = counter[num]
                maxnum = num
        return maxnum

class Solution(object):
    def majorityElement(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        cur_num = None
        cnt = 0
        for i in range(len(nums)):
            if cnt == 0:
                cur_num = nums[i]
            if cur_num == nums[i]:
                cnt += 1
            else:
                cnt -= 1
        return cur_num

class Solution {
    public int majorityElement(int[] nums) {
        if(nums.length==1){
            return nums[0];
        }
        Arrays.sort(nums);
        int i=0;
        int ansMax =-1;
        int count =0;
        while(i+1<=nums.length-1){

            if(nums[i]==nums[i+1]){
                count++;
                if(count>=(nums.length)/2){
                    ansMax = nums[i];
                }
            }
            else{
                count=0;
            }
            i++;
        }
        return ansMax;

    }
}

public class MajorityElement {
    public static int majorityElement(int[] nums) {
        int count = 0, candidate = 0;

        int i = 0;
        while (i < nums.length) {
            if (count == 0) {
                candidate = nums[i];
                count = 1;
            } else {
                count += (nums[i] == candidate) ? 1 : -1;
            }
            i++;
        }
        return candidate;
    }

    public static void main(String[] args) {
        int[] nums = {6,5,5};
        System.out.println(majorityElement(nums));
    }
}
